        "rawMessageText": "",
        "url": "https://cdn.discordapp.com/attachments/1269536886586609695/1346014878871195658/dont_give_up.mp4?ex=6b05df4a&is=6b048dca&hm=5f7d1d2aaa063324a9aa312f6454c86726c4b8e52bc662ae409f1a4c915dc544&",
        "originalUrl": "https://cdn.discordapp.com/attachments/1269536886586609695/1346014878871195658/dont_give_up.mp4?ex=6b05df4a&is=6b048dca&hm=5f7d1d2aaa063324a9aa312f6454c86726c4b8e52bc662ae409f1a4c915dc544&",
        "proxyUrl": "https://media.discordapp.net/attachments/1269536886586609695/1346014878871195658/dont_give_up.mp4?ex=6b05df4a&is=6b048dca&hm=5f7d1d2aaa063324a9aa312f6454c86726c4b8e52bc662ae409f1a4c915dc544&",
